// Run: node tests/path-render.test.js — renders every Path screen (every station × 7 days, station pages, all tabs) against a stub DOM
const { M, render, stub, badText } = require('./_harness.js');
let pass = 0, fail = 0;
const ok = (name, cond, extra = '') => { if (cond) pass++; else { fail++; console.log('FAIL', name, extra === '' ? '' : JSON.stringify(extra).slice(0, 300)); } };

const N = M.PATH_STATIONS.length;
const stationIds = new Set(M.PATH_STATIONS.map((s) => s.id));

/* start screen */
{ const r = render(['today']); ok('start screen renders', r.body.includes('Begin at the beginning') && !badText(r.body)); }

/* every station × every day */
let blank = 0, links = 0, brokenLinks = [], unlinked = [], shelfBooks = 0;
const shelfLinked = (body, id) => body.includes(`<li data-lib="${id}"><a class="sh-t" href="#/path/read/${id}">`);      /* a book of a study shelf or of “Compare with” is a link that opens it in the reader */
for (let i = 0; i < N; i++) {
  for (const prompts of [false, true]) {      /* the questions for reflection are off until a person turns them on: every screen is drawn both ways */
    M.store.set('path.state', { started: '2026-11-14', cur: i, days: {}, notes: {}, read: {}, rule: '', prompts });
    for (let d = 1; d <= 7; d++) {
      const r = render(['today'], { day: String(d) });
      const s = M.PATH_STATIONS[i];
      if (badText(r.body)) ok(`station ${i} day ${d} has no bad text`, false, r.body.match(/.{30}(undefined|\[object|NaN|>null<).{30}/));
      if (!r.body.includes(s.title.replace(/"/g, '&quot;'))) ok(`station ${i} day ${d} shows its title`, false, s.title);
      const pday = (r.body.match(/<div class="pday">([\s\S]*?)<\/div>\s*(?:<div class="pq">|<div class="row")/) || [])[1] || '';
      if (pday.length < 20) { blank++; ok(`station ${i} day ${d} has content`, false, pday.length); }
      if (prompts !== r.body.includes('Today’s question') || prompts !== r.body.includes('class="pq"') || prompts !== r.body.includes(`data-note="${s.id}.${d}"`)) ok(`station ${i} day ${d} shows its question exactly when the questions are on`, false, prompts);
      if (!r.body.includes(`data-prompts="${prompts ? 0 : 1}" aria-pressed="${prompts}"`) || !r.body.includes(`Questions for reflection: ${prompts ? 'on' : 'off'}`)) ok(`station ${i} day ${d} has the switch for the questions, set as saved`, false, prompts);
      if (d === 5 && !r.body.includes(`data-run="${s.practice}"`)) ok(`station ${i} day 5 has a Begin button`, false, s.practice);
      if (d === 2 && prompts) [...s.shelf, ...s.again].forEach((id) => { shelfBooks++; if (!shelfLinked(r.body, id)) unlinked.push(`${s.id} day 2 ${id}`); });
      (r.body.match(/#\/path\/station\/(s\d+)/g) || []).forEach((l) => { links++; if (!stationIds.has(l.split('/').pop())) brokenLinks.push(l); });
    }
    const sp = render(['station', M.PATH_STATIONS[i].id]);
    if (badText(sp.body) || !sp.body.includes('Station ' + (i + 1) + ' of ')) ok(`station page ${i}`, false, sp.body.slice(0, 80));
    if (prompts !== sp.body.includes('<div class="eyebrow" style="margin-top:10px">Questions</div>') || !sp.body.includes(`Questions for reflection: ${prompts ? 'on' : 'off'}`)) ok(`station page ${i} lists its questions exactly when they are on, and has the switch`, false, prompts);
    if (prompts) [...M.PATH_STATIONS[i].shelf, ...M.PATH_STATIONS[i].again].forEach((id) => { shelfBooks++; if (!shelfLinked(sp.body, id)) unlinked.push(`${M.PATH_STATIONS[i].id} page ${id}`); });
    (sp.body.match(/#\/path\/station\/(s\d+)/g) || []).forEach((l) => { links++; if (!stationIds.has(l.split('/').pop())) brokenLinks.push(l); });
  }
}
ok('every book on a station’s study shelf, and in its “Compare with”, is a link that opens it in the reader (on the station page and on day 2: the first station, “The first dead”, has only a shelf)', shelfBooks > 600 && unlinked.length === 0, [shelfBooks, unlinked.slice(0, 5)]);
ok('all 959 day screens have content, with the questions off and on', blank === 0, blank);
ok('no broken station links', brokenLinks.length === 0, brokenLinks.slice(0, 5));
ok('station links were exercised', links > 500, links);

/* the questions for reflection: off until turned on, and remembered with the Journey's saved state (nothing else about the saved state changes shape) */
