  M.PATH.upd((s) => { s.prompts = true; }); const on = M.PATH.get(); ok('turning them on is remembered, and the notes, the rule and the place are untouched', on.prompts === true && on.notes['s001.d1'] === 'kept' && on.rule === 'my rule' && on.cur === 2 && on.started === '2026-11-14');
