    ok('reader: shows title, translator, licence, section and verse numbers', h.includes('Genesis') && h.includes('World English Bible') && h.includes('Public domain') && h.includes('Chapter 1') && (h.match(/class="vn"/g) || []).length === 3, h.slice(0, 120));
